/* AIVIC_FUNCTION_BUNDLE_START owner=aggregateMonthlySalesAndInvoices exports=aggregateMonthlySalesAndInvoices */
const __aivicBundle_15_aggregateMonthlySalesAndInvoices = (() => {
  function aggregateMonthlySalesAndInvoices(params: {
    period_start: Date;
    period_end: Date;
    transactions: Array<{
      transaction_id: string;
      customer_id: string;
      invoice_date: Date;
      invoice_amount: number;
      sales_amount: number;
      invoice_status: string;
      sales_status: string;
    }>;
  }): AggregationResult {
    const { period_start, period_end, transactions } = params;
  
    let total_invoice_amount = 0;
    let total_sales_amount = 0;
    const transaction_details: Array<{
      transaction_id: string;
      customer_id: string;
      invoice_amount: number;
      sales_amount: number;
      match_status: string;
    }> = [];
  
    for (const transaction of transactions) {
      const invoiceDate = new Date(transaction.invoice_date);
  
      if (invoiceDate >= period_start && invoiceDate <= period_end) {
        total_invoice_amount += transaction.invoice_amount;
        total_sales_amount += transaction.sales_amount;
  
        const match_status =
          transaction.invoice_amount === transaction.sales_amount
            ? "matched"
            : "mismatched";
  
        transaction_details.push({
          transaction_id: transaction.transaction_id,
          customer_id: transaction.customer_id,
          invoice_amount: transaction.invoice_amount,
          sales_amount: transaction.sales_amount,
          match_status,
        });
      }
    }
  
    const discrepancy = Math.abs(total_invoice_amount - total_sales_amount);
    const amounts_match = discrepancy === 0;
  
    return {
      total_invoice_amount,
      total_sales_amount,
      transaction_count: transaction_details.length,
      amounts_match,
      discrepancy,
      transaction_details,
    };
  }
  return { aggregateMonthlySalesAndInvoices };
})();
export const aggregateMonthlySalesAndInvoices = __aivicBundle_15_aggregateMonthlySalesAndInvoices.aggregateMonthlySalesAndInvoices;
