      approvalHour >= systemConfig.businessHoursStart &&
      approvalHour < systemConfig.businessHoursEnd;
  
    // 承認日付を YYYY-MM-DD 形式で取得
    const approvalDateStr = approvalTime.toISOString().split('T')[0];
