/* AIVIC_FUNCTION_BUNDLE_START owner=calculateAverageROI exports=calculateAverageROI */
const __aivicBundle_54_calculateAverageROI = (() => {
  function calculateAverageROI(input: {
    initialInvestment: number;
    yearlyInvestments: number[];
    yearlyProfits: number[];
  }): {
    totalInvestment: number;
    totalProfit: number;
    averageROI: number;
  } {
    const { initialInvestment, yearlyInvestments, yearlyProfits } = input;
  
    // 総投資額を計算: 初期投資 + 各年度投資額の合計
    const totalInvestment = initialInvestment + yearlyInvestments.reduce((sum, inv) => sum + inv, 0);
  
    // 総利益を計算: 各年度利益の合計
    const totalProfit = yearlyProfits.reduce((sum, profit) => sum + profit, 0);
  
    // 年平均ROIを計算: (総利益 / 総投資額) × 100
    const averageROI = totalInvestment > 0 ? (totalProfit / totalInvestment) * 100 : 0;
  
    return {
      totalInvestment,
      totalProfit,
      averageROI,
    };
  }
  return { calculateAverageROI };
})();
export const calculateAverageROI = __aivicBundle_54_calculateAverageROI.calculateAverageROI;
