/* AIVIC_FUNCTION_BUNDLE_START owner=calculateROIPaybackPeriod exports=calculateROIPaybackPeriod */
const __aivicBundle_55_calculateROIPaybackPeriod = (() => {
  interface CalculateROIPaybackPeriodInput {
    investment_amount: number;
    monthly_profit: number;
  }
  
  interface CalculateROIPaybackPeriodResult {
    payback_period_months: number;
    payback_period_years: number;
    is_within_one_year: boolean;
  }
  
   function calculateROIPaybackPeriod(
    input: CalculateROIPaybackPeriodInput
  ): CalculateROIPaybackPeriodResult {
    const { investment_amount, monthly_profit } = input;
  
    if (investment_amount <= 0) {
      throw new Error("投資額は0より大きい値である必要があります");
    }
  
    if (monthly_profit <= 0) {
      throw new Error("月次利益は0より大きい値である必要があります");
    }
  
    const payback_period_months_exact = investment_amount / monthly_profit;
  
    const payback_period_months = Math.round(payback_period_months_exact * 100) / 100;
  
    const payback_period_years = Math.floor(payback_period_months / 12);
  
    const is_within_one_year = payback_period_months < 12;
  
    return {
      payback_period_months,
      payback_period_years,
      is_within_one_year,
    };
  }
  return { calculateROIPaybackPeriod };
})();
export const calculateROIPaybackPeriod = __aivicBundle_55_calculateROIPaybackPeriod.calculateROIPaybackPeriod;
